count=0
if [ "${1:-}" = --count ]; then count=1; shift; fi
rows=$(grep -v '^#' "$BOOKINGS" | awk -F'\t' -v d="${1:-}" 'NF && (d == "" || $2 == d) { printf "%s %s-%s %s %s\n", $2, $3, $4, $1, $5 }' | sort)
if [ $count = 1 ]; then [ -z "$rows" ] && echo 0 || printf '%s\n' "$rows" | wc -l; exit 0; fi
[ -z "$rows" ] || printf '%s\n' "$rows"

